        try:
            with timer as t:
                entered_self = entered_self and (t is timer)
                if i in failing_blocks:
                    raise RuntimeError("boom")
        except RuntimeError:
            escaped += 1
    return [timer.laps, timer.total, timer.elapsed, escaped, entered_self]

