def _move(pos, vel, limit):
    pos += vel
    if pos < 0:
        pos, vel = -pos, -vel
    elif pos > limit:
        pos, vel = 2 * limit - pos, -vel
    return pos, vel

def simulate(x, y, vx, vy, width, height, ticks):
    for _ in range(ticks):
        x, vx = _move(x, vx, width)
        y, vy = _move(y, vy, height)
    return [x, y, vx, vy]

